import RegExpUtils from "./RegExpUtils";

/**
 * The line every generated file's banner carries, which is also the marker
 * header discovery reads back to recognize a header the transpiler wrote
 * (#2168). The line's shape is decided here once: `line()` writes it and
 * `marker()`/`sourcePathMarker()` read it, so the writers and the reader
 * cannot drift.
 */
class GeneratedBanner {
  /** Names the tool; the whole marker when no source is recorded */
  static readonly TEXT = "generated by cnx";

  /** Introduces the recorded source path, as in `from: led.cnx` */
  private static readonly FROM = "from:";

  /**
   * What may come before the text on its line: a comment leader and nothing
   * else. `line()` writes ` * `; a one-line `//` or `/*` banner reads the
   * same. A comment that only mentions the text is not a banner.
   */
  private static readonly LINE_START = String.raw`^[ \t]*(?:\*|//|/\*)[ \t]*`;

  /**
   * What may follow the text: whitespace, a comment's close or the line's end.
   * `cnx-gen` and `cnx.py` name some other tool.
   */
  private static readonly TEXT_END = String.raw`(?=\s|\*\/|$)`;

  /** The banner's comment line: ` * generated by cnx[ from: <sourcePath>]` */
  static line(sourcePath?: string): string {
    return sourcePath
      ? ` * ${GeneratedBanner.withSource(GeneratedBanner.TEXT, sourcePath)}`
      : ` * ${GeneratedBanner.TEXT}`;
  }

  /**
   * Matches a banner line carrying `text` -- this banner's `TEXT`, or the text
   * an earlier release wrote -- with or without a recorded source.
   */
  static marker(text: string): RegExp {
    return new RegExp(
      GeneratedBanner.LINE_START +
        RegExpUtils.escape(text) +
        GeneratedBanner.TEXT_END,
      "m",
    );
  }

  /**
   * Matches a banner line carrying `text` that records a source; group 1 is
   * the path, which must be on the banner's own line.
   */
  static sourcePathMarker(text: string): RegExp {
    return new RegExp(
      GeneratedBanner.LINE_START +
        RegExpUtils.escape(GeneratedBanner.withSource(text, "")) +
        String.raw`[ \t]*(\S+)`,
      "m",
    );
  }

  /** `<text> from: <sourcePath>` */
  private static withSource(text: string, sourcePath: string): string {
    return `${text} ${GeneratedBanner.FROM} ${sourcePath}`;
  }
}

export default GeneratedBanner;
